import{_ as t,o as a,c as o,a8 as r}from"./chunks/framework.R_sesYpn.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","order":-1},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786534448000}'),n={name:"guide/index.md"};function s(i,e,l,c,u,d){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="what-is-blacklab" tabindex="-1">What is BlackLab? <a class="header-anchor" href="#what-is-blacklab" aria-label="Permalink to &quot;What is BlackLab?&quot;">​</a></h1> <p>BlackLab is a corpus search engine built on top of <a href="http://lucene.apache.org/" target="_blank" rel="noreferrer">Apache Lucene</a>. It supports token-based querying and querying (dependency) relations.</p> <details class="details custom-block"><summary><b>What is a corpus search engine?</b></summary> <p>A corpus search engine allows you to search through large bodies of annotated text. Each word can have a number of annotations such as headword, part of speech, etc. Spans of text may be annotated, and there may be (dependency) relations between (groups of) words. You can search all of these, looking for specific patterns.</p> <p>For example, the word <em>chickens</em> would be tagged with the headword <em>chicken</em> and the part of speech <em>(plural) noun</em>.</p> <p>An example of a query could be: find adjectives occurring before the headword <em>chicken</em>. This might find matches like &quot;small chicken&quot; or &quot;black spotted chickens&quot;. Of course, much more complex queries can be crafted as well.</p> <p>You may also have annotations on spans (groups of words); for example, named entities like <em>Albert Einstein</em> or <em>The Eiffel Tower</em>. Other tags could include paragraphs and sentences. You can incorporate all these annotations in your queries as well.</p> <p>Even if your corpus does not include annotations, you can still benefit from other features that a corpus engine provides, such as sorting hits by the word before the hit, or grouping on the matched text.</p></details> <p>BlackLab was designed primarily for linguists, but is also used for other purposes, like historical research and knowledge extraction; anyone who wants to find patterns in text.</p> <p>You can use it from any programming language using the REST API.</p> <p>BlackLab was developed at the <a href="https://ivdnt.org" target="_blank" rel="noreferrer">Dutch Language Institute</a>. It is free and open source software (Apache License 2.0).</p> <div class="tip custom-block"><p class="custom-block-title">BlackLab present and future</p> <p>BlackLab 4 shipped with major new features, including <a href="https://blacklab.ivdnt.org/guide/query-language/relations.html" target="_blank" rel="noreferrer">dependency relations</a> and <a href="https://blacklab.ivdnt.org/guide/query-language/parallel.html" target="_blank" rel="noreferrer">parallel corpora</a>. See the <a href="https://github.com/instituutnederlandsetaal/BlackLab/releases/tag/v4.0.0" target="_blank" rel="noreferrer">release notes</a> and the <a href="https://blacklab.ivdnt.org/development/changelog.html" target="_blank" rel="noreferrer">full changelog</a>.</p> <p>Try the <code>dev</code> branch for better performance, expanded plugin support, and many other improvements that will land in BlackLab 5.</p></div> <h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2> <p>BlackLab&#39;s features:</p> <ul><li><strong>Index annotated data</strong>: flexibly handles different input formats with any kind of annotations (e.g. headword/part-of-speech, named entities, etc.)</li> <li><strong>Search for complex patterns</strong> using the powerful <a href="./query-language/">query language BCQL</a> (see below)</li> <li><strong>Group and sort</strong> result sets on many criteria, such as the text preceding the match.</li> <li><strong>Highlight</strong> hits in a document and keyword-in-context (KWIC) view of hits.</li> <li><strong>Fast and scalable</strong>: supports searching corpora with billions of tokens</li> <li><strong>Easy to use</strong>, well-documented REST API</li> <li><strong>Highly customizable using plugins</strong>. Add your own data preprocessors, query functions, etc. (try on the dev branch or wait for v5)</li> <li><strong>Mature and actively developed</strong> since 2010</li></ul> <p>Examples of search features:</p> <ul><li><strong>Token-based querying</strong><br>To find <em>dog</em> or <em>cat</em> followed within 10 tokens by one or more adjectives and a word starting with <em>friend</em>:<br><code>[lemma=&quot;dog|cat&quot;] []{1,10} [pos=&quot;ADJ&quot;]+ &quot;friend.*&quot;</code></li> <li><strong>Search within spans</strong><br>To find named entities such as  <em>Sir Barkington the Third</em>:<br><code>&lt;ne/&gt; containing &quot;bark.*&quot;</code></li> <li><strong>Find collocations</strong><br> (try on the dev branch or wait for v5)<br>To find nouns that occur close to <em>paw</em> within a sentence:<br><code>meet_within([pos=NOUN], [lemma=&quot;paw&quot;], &lt;s/&gt;, -3, 3)</code></li> <li><strong>Search (dependency or other) relations</strong><br>To find nominal subjects for the verb <em>pet</em><br><code>[lemma=&quot;pet&quot; &amp; pos=&quot;VERB&quot;] -nsubj-&gt; [pos=&quot;NOUN&quot;]</code></li> <li><strong>Search parallel corpora</strong>, such as different languages or historical versions.<br>To find Dutch translations for <em>good dog</em> and <em>bad dog</em><br><code>&quot;good|bad&quot; &quot;dog&quot; ==&gt;nl _</code></li> <li><strong>Capture parts of matches</strong><br>Capture the noun after <em>canine</em> or <em>feline</em> as A<br><code>&quot;canine|feline&quot; A:[pos=&quot;NOUN&quot;] within &lt;s/&gt;</code></li></ul> <h2 id="try-it-out" tabindex="-1">Try it out <a class="header-anchor" href="#try-it-out" aria-label="Permalink to &quot;Try it out&quot;">​</a></h2> <p>To see BlackLab and BlackLab Frontend in action, have a look at either of these:</p> <ul><li><a href="https://brievenalsbuit.ivdnt.org/" target="_blank" rel="noreferrer">Brieven als Buit</a> (&quot;Letters as Loot&quot;), where you can search a collection of historical letters to and from sailors from the 17th to the 19th century</li> <li><a href="https://corpusgysseling.ivdnt.org/" target="_blank" rel="noreferrer">Corpus Gysseling</a>, a small corpus of historic Dutch (1200-1300)</li></ul> <p>With a <a href="https://idm.clarin.eu/unitygw/pub#!registration-CLARIN%20Identity%20Registration" target="_blank" rel="noreferrer">free CLARIN account</a> account, you can also check out:</p> <ul><li><a href="https://chn.ivdnt.org/" target="_blank" rel="noreferrer">Corpus Hedendaags Nederlands</a></li> <li><a href="https://opensonar.ivdnt.org/" target="_blank" rel="noreferrer">OpenSonar</a></li></ul> <p>(others can be found in the <a href="./who-uses-blacklab.html">Who uses BlackLab?</a> section)</p> <p>Here are a few searches you can try (use the <em>Extended</em> tab for these):</p> <ul><li><strong>Lemma: <em>koe</em></strong> Finds all forms of the word &quot;koe&quot; (cow)<br>
Other words to try: <em>wet</em> (law), <em>zien</em> (to see), <em>groot</em> (large)</li> <li><strong>Part of speech: <em>NOU-C</em></strong> Find all common nouns<br>
Other values to try: <em>VRB</em> (verbs), <em>ADJ</em> (adjectives)</li> <li><em><em>Word: _hoe</em>_</em>* Find words starting with &quot;hoe&quot;</li></ul> <p>To learn how to get BlackLab up and running yourself, move on to <a href="./getting-started.html">Getting Started</a>.</p>`,41)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
